#ifndef FAKE_I2C_H
#define FAKE_I2C_H

/* Fake gt_i2c_ops for driver tests: no /dev/i2c-1, no real sleeping.
 *
 * A test declares a fake_i2c on the stack, scripts read data and failures,
 * passes fake_i2c_bus(&f) to the driver, then inspects what the driver did:
 * bytes written, read attempts, waits and closes. The fake is the bus ctx
 * and is owned by the test, so close() only counts and never frees.
 * fake_i2c_bus() zeroes the fake, so call it before scripting anything.
 *
 * Header-only (static inline) because the Makefile links each test .c with
 * src/ only; inline keeps unused helpers from tripping -Werror. */
#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include "i2c_bus.h"

#define FAKE_I2C_MAX_WRITTEN 64
#define FAKE_I2C_MAX_READ    64

typedef struct {
    /* Every attempted write, in order (failed ones too: the bus was driven). */
    uint8_t  written[FAKE_I2C_MAX_WRITTEN];
    size_t   n_written;
    int      write_calls;

    /* Scripted read data, consumed front to back across read() calls. */
    uint8_t  read_data[FAKE_I2C_MAX_READ];
    size_t   n_read_data;
    size_t   read_pos;
    int      read_calls;

    /* Failure injection: the next N calls of each kind return GT_ERR_IO. */
    int      fail_writes;
    int      fail_reads;
    /* Fail only the Nth write call (1-based, counted since fake_i2c_bus);
     * 0 = off. Lets a test pass the first commands and NACK a later one. */
    int      fail_write_at;

    int      sleep_calls;
    uint32_t slept_ms_total;
    int      closed;
} fake_i2c;

/* Append `len` bytes to the data later reads will return. */
static inline void fake_i2c_push_read(fake_i2c *f, const uint8_t *buf, size_t len)
{
    for (size_t i = 0; i < len && f->n_read_data < FAKE_I2C_MAX_READ; i++) {
        f->read_data[f->n_read_data++] = buf[i];
    }
}

static inline gt_status fake_i2c_write(void *ctx, const uint8_t *buf, size_t len)
{
    fake_i2c *f = ctx;
    f->write_calls++;
    for (size_t i = 0; i < len && f->n_written < FAKE_I2C_MAX_WRITTEN; i++) {
        f->written[f->n_written++] = buf[i];
    }
    if (f->fail_writes > 0) {
        f->fail_writes--;
        return GT_ERR_IO;
    }
    if (f->fail_write_at == f->write_calls) {
        return GT_ERR_IO;
    }
    return GT_OK;
}

/* A failed read consumes no data. Running out of scripted data is a short
 * read, which the real bus also reports as GT_ERR_IO. */
static inline gt_status fake_i2c_read(void *ctx, uint8_t *buf, size_t len)
{
    fake_i2c *f = ctx;
    f->read_calls++;
    if (f->fail_reads > 0) {
        f->fail_reads--;
        return GT_ERR_IO;
    }
    if (f->n_read_data - f->read_pos < len) {
        return GT_ERR_IO;
    }
    memcpy(buf, &f->read_data[f->read_pos], len);
    f->read_pos += len;
    return GT_OK;
}

static inline void fake_i2c_sleep_ms(void *ctx, uint32_t ms)
{
    fake_i2c *f = ctx;
    f->sleep_calls++;
    f->slept_ms_total += ms;
}

static inline void fake_i2c_close(void *ctx)
{
    fake_i2c *f = ctx;
    f->closed++;
}

/* Reset `f` and return a bus that routes every op to it. */
static inline gt_i2c_bus fake_i2c_bus(fake_i2c *f)
{
    static const gt_i2c_ops ops = {
        .write    = fake_i2c_write,
        .read     = fake_i2c_read,
        .sleep_ms = fake_i2c_sleep_ms,
        .close    = fake_i2c_close,
    };
    memset(f, 0, sizeof *f);
    return (gt_i2c_bus){ .ops = &ops, .ctx = f };
}

#endif
#ifndef FAKE_SOCK_H
#define FAKE_SOCK_H

/* Fake gt_sock_ops for IPC client and hub sender tests: no socket, no
 * peer, no waiting. Sender tests also script recv() replies (seq_resume)
 * and set expected_len to 24.
 *
 * A test declares a fake_sock on the stack, passes fake_sock_ops(&f) and &f
 * to gt_ipc_client_open_ops, scripts connect failures and send results,
 * then inspects what the client did: connect attempts, frames sent,
 * disconnects and the final destroy. The fake is the ctx and is owned by
 * the test, so destroy() only counts and never frees. fake_sock_ops()
 * zeroes the fake, so call it before scripting anything.
 *
 * Header-only (static inline) for the same reason as fake_i2c.h: the
 * Makefile links each test .c with src/ only, and inline keeps unused
 * helpers from tripping -Werror. */
#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include "ipc_sock.h"

#define FAKE_SOCK_MAX_SENT    1100  /* a full hub queue (1024) plus GAPs and
                                     * new records; also two client rings */
#define FAKE_SOCK_MAX_RESULTS 64
#define FAKE_SOCK_MAX_REPLIES 16
/* Largest frame the fake keeps: the hub sender's 24 B record (GT_REC_SIZE
 * in log_record.h). The sensor client's 16 B messages fit in the front. */
#define FAKE_SOCK_MAX_FRAME   24

/* One scripted recv() outcome. result GT_OK with len 0 is "nothing has
 * arrived yet"; GT_OK with len > 0 delivers bytes[0..len-1]; GT_ERR_IO is
 * "storage closed the connection". */
typedef struct {
    gt_status result;
    uint8_t   bytes[FAKE_SOCK_MAX_FRAME];
    size_t    len;
} fake_sock_reply;

typedef struct {
    /* connect(): the next fail_connects calls return GT_ERR_IO. */
    int      connect_calls;
    int      fail_connects;
    int      connected;

    /* send(): scripted results, used front to back, one per call; once
     * they run out every send returns GT_OK. */
    gt_status send_results[FAKE_SOCK_MAX_RESULTS];
    size_t    n_send_results;
    size_t    send_result_pos;
    int       send_calls;

    /* Every frame send() returned GT_OK for, in order: what the peer got.
     * sent_len[i] is that frame's length (16 for a message, 24 for a
     * record); a longer frame keeps only its first FAKE_SOCK_MAX_FRAME. */
    uint8_t  sent[FAKE_SOCK_MAX_SENT][FAKE_SOCK_MAX_FRAME];
    size_t   sent_len[FAKE_SOCK_MAX_SENT];
    size_t   n_sent;
    /* The frame length a correct caller sends; 0 (what fake_sock_ops
     * leaves) means GT_MSG_SIZE, the sensor client's. Hub sender tests set
     * it to 24. */
    size_t   expected_len;

    /* recv(): scripted replies, used front to back, one per call; once
     * they run out every recv returns "nothing has arrived yet". */
    fake_sock_reply recv_replies[FAKE_SOCK_MAX_REPLIES];
    size_t   n_recv_replies;
    size_t   recv_reply_pos;
    int      recv_calls;

    int      disconnect_calls;
    int      destroy_calls;

    /* Client bugs the fake can see; a correct client leaves these at 0. */
    int      connect_while_connected;
