37	/* Write a valid header, then one light DATA record per entry of `seqs`,
38	 * into `segment`. Returns the segment's length in bytes. */
39	static size_t build_segment(uint8_t segment[SEGMENT_BUF_SIZE],
40	                            const uint32_t *seqs, size_t seq_count)
41	{
42	    const gt_seg_header header = { .created_at_us = 1000 };
43	    memset(segment, 0, SEGMENT_BUF_SIZE);
44	    CHECK_EQ(gt_seg_header_encode(&header, segment), GT_OK);
45	
46	    for (size_t record_index = 0; record_index < seq_count; record_index++) {
47	        const gt_record record = {
48	            .type = GT_REC_DATA, .sensor_id = GT_SENSOR_LIGHT,
49	            .seq = seqs[record_index], .timestamp_us = 2000 + record_index,
50	            .value = 100 + (uint32_t)record_index,
51	        };
52	        CHECK_EQ(gt_record_encode(&record, &segment[RECORD_OFFSET(record_index)]), GT_OK);
53	    }
54	    return RECORD_OFFSET(seq_count);
55	}
