 * reuses yesterday's, and a record stamped 23:00 on the 25th lands there,
 * in the file for its own day. No file for the 26th exists yet. */
static void test_sop17_restart_reuses_yesterday(void)
{
    const gt_file_ops *ops = fake_fs_ops(&fs);
    const uint32_t seqs[] = { 1, 2, 3 };
    put_segment(YESTERDAY, seqs, 3);
    size_t yesterday_len = fake_fs_file(&fs, YESTERDAY)->len;
    gt_storage_open_info info;
    gt_storage *storage = open_ok(ops, TODAY_US, &info);

    CHECK(strcmp(info.active_name, YESTERDAY) == 0);
    CHECK_EQ(info.created, 0);
    CHECK(fake_fs_file(&fs, TODAY_NAME) == NULL);

    const gt_record late_yesterday = {
        .type = GT_REC_DATA, .sensor_id = GT_SENSOR_LIGHT, .seq = 4,
        .timestamp_us = TODAY_US - (uint64_t)2 * 3600u * 1000000u,   /* 25th, 23:00 */
        .value = 7,
    };
    uint8_t wire[GT_REC_SIZE];
    CHECK_EQ(gt_record_encode(&late_yesterday, wire), GT_OK);
    CHECK_EQ(gt_storage_append(storage, wire, 0, NULL), GT_OK);
