/* ---- SRO-16: a backlog over two midnights fills three files ----
 * Storage was cut off for two days, and the 26th, 27th and 28th each
 * left one record pending. Rollover writes the 26th's into today's file,
 * makes the 27th's file for its record, then the 28th's file, each one
 * only once a record dated that day is pending (PF-21). The 28th's
 * record, in the now-active file's own day, waits for the normal flush,
 * so batching is untouched. */
static void test_sro16_backlog_fills_each_day(void)
{
    const gt_file_ops *ops = fake_fs_ops(&fs);
    gt_storage *storage = open_today(ops);
    append_stamped(storage, 1, TODAY_US);
    append_stamped(storage, 2, TOMORROW_US + 3600u * US_PER_S);
    append_stamped(storage, 3, DAY_AFTER_US);

    rollover_expect(storage, DAY_AFTER_US, 1, GT_OK, GT_STORAGE_EV_ROLLOVER);
    CHECK_EQ(fake_fs_file(&fs, TODAY_NAME)->synced_len, GT_SEG_HEADER_SZ + GT_REC_SIZE);
    CHECK(fake_fs_file(&fs, TOMORROW_NAME) != NULL);
    CHECK(fake_fs_file(&fs, DAY_AFTER_NAME) != NULL);
    if (fake_fs_file(&fs, TOMORROW_NAME) != NULL && fake_fs_file(&fs, DAY_AFTER_NAME) != NULL) {
        CHECK_EQ(fake_fs_file(&fs, TOMORROW_NAME)->synced_len, GT_SEG_HEADER_SZ + GT_REC_SIZE);
        CHECK_EQ(fake_fs_file(&fs, DAY_AFTER_NAME)->synced_len, GT_SEG_HEADER_SZ);
    }
    CHECK_EQ(read_stats(storage).pending, 1);

    CHECK_EQ(gt_storage_flush(storage, NULL), GT_OK);
    if (fake_fs_file(&fs, DAY_AFTER_NAME) != NULL) {
        CHECK_EQ(fake_fs_file(&fs, DAY_AFTER_NAME)->synced_len, GT_SEG_HEADER_SZ + GT_REC_SIZE);
    }
    gt_storage_close(storage);
}

/* ---- SRO-17: a new day with no record for it makes no file ----
 * The clock has passed midnight, but the only pending record is the old
 * day's. Rollover makes no file for the new day (an idle day leaves
 * none), writes nothing, and leaves the record for the normal flush,
 * which puts it in its own day's file. */
static void test_sro17_no_record_no_new_file(void)
{
    const gt_file_ops *ops = fake_fs_ops(&fs);
    gt_storage *storage = open_today(ops);
    append_stamped(storage, 1, TODAY_US);
    int pwrites_before = fs.pwrite_calls;

    rollover_expect(storage, TOMORROW_US, 1, GT_OK, 0);
    CHECK(fake_fs_file(&fs, TOMORROW_NAME) == NULL);
    CHECK_EQ(fs.pwrite_calls, pwrites_before);
    CHECK_EQ(read_stats(storage).pending, 1);

    CHECK_EQ(gt_storage_flush(storage, NULL), GT_OK);
    CHECK_EQ(fake_fs_file(&fs, TODAY_NAME)->synced_len, GT_SEG_HEADER_SZ + GT_REC_SIZE);
    gt_storage_close(storage);
}

/* ---- SRO-18: a new file's header has its first record's time ----
 * The 27th's file is made for a record stamped 05:00 on the 27th; its
 * header says when the file's day began being written, from that
 * record, not from the storage clock (06:00 here). */
static void test_sro18_header_from_first_record(void)
{
    const gt_file_ops *ops = fake_fs_ops(&fs);
    gt_storage *storage = open_today(ops);
    const uint64_t first_us = TOMORROW_US + 5u * 3600u * US_PER_S;
    append_stamped(storage, 1, first_us);

    rollover_expect(storage, TOMORROW_US + 6u * 3600u * US_PER_S, 1, GT_OK,
                    GT_STORAGE_EV_ROLLOVER);
    const fake_file *tomorrow = fake_fs_file(&fs, TOMORROW_NAME);
    CHECK(tomorrow != NULL);
    if (tomorrow != NULL) {
        gt_seg_header header;
        CHECK_EQ(gt_seg_header_decode(tomorrow->synced_data, &header), GT_OK);
        CHECK(header.created_at_us == first_us);
    }
    gt_storage_close(storage);
}

