    const fake_file *yesterday = fake_fs_file(&fs, TODAY_NAME);
    CHECK_EQ(yesterday->len, GT_SEG_HEADER_SZ);
    CHECK_EQ(yesterday->synced_len, GT_SEG_HEADER_SZ);

