 * SIGTERM comes just after midnight with a record from each day pending.
 * The final flush can't put the new day's record in today's file (PF-21),
 * so shutdown makes the new day's file for it (ROLLOVER) and commits
 * each record to its own day. Nothing is left behind, so the marker is
 * written and the shutdown counts as clean. */
static void test_scl11_shutdown_across_midnight(void)
{
    const gt_file_ops *ops = fake_fs_ops(&fs);
    gt_storage *storage = open_storage(ops, NULL);
    const uint64_t tomorrow_us = (uint64_t)1793059200u * 1000000u;   /* 2026-10-27 00:00 UTC */
    const gt_record records[2] = {
        { .type = GT_REC_DATA, .sensor_id = GT_SENSOR_LIGHT, .seq = 1,
          .timestamp_us = TODAY_US, .value = 201 },
        { .type = GT_REC_DATA, .sensor_id = GT_SENSOR_LIGHT, .seq = 2,
          .timestamp_us = tomorrow_us, .value = 202 },
    };
    /* Invariant: records[0 .. record_index - 1] have been appended. */
    for (size_t record_index = 0; record_index < 2; record_index++) {
        uint8_t wire[GT_REC_SIZE];
        CHECK_EQ(gt_record_encode(&records[record_index], wire), GT_OK);
        CHECK_EQ(gt_storage_append(storage, wire, 0, NULL), GT_OK);
    }

    shutdown_expect(storage, GT_OK, GT_STORAGE_EV_ROLLOVER);
    CHECK_EQ(fake_fs_file(&fs, TODAY_NAME)->synced_len, RECORD_OFFSET(1));
    const fake_file *tomorrow = fake_fs_file(&fs, "log-20261027.bin");
    CHECK(tomorrow != NULL);
    if (tomorrow != NULL) {
        CHECK_EQ(tomorrow->synced_len, RECORD_OFFSET(1));
    }
    CHECK_EQ(marker_durable(), 1);
    gt_storage_stats stats;
    CHECK_EQ(gt_storage_read_stats(storage, &stats), GT_OK);
    CHECK_EQ(stats.pending, 0);
    gt_storage_close(storage);
}

