/* The marker is an empty file, so only its directory entry has to be
 * made durable: fsync_dir, no fsync of the file itself. */
gt_status gt_storage_shutdown(gt_storage *storage, unsigned *events_out)
{
    if (events_out != NULL) {
        *events_out = 0;
    }
    if (storage == NULL) {
        return GT_ERR_INVAL;
    }

    /* Every pending record goes into its own day's file first, with the
     * same moves rollover makes but no retention (PF-21): a later-dated
     * record the final flush had to leave behind would be lost. */
    unsigned events = 0;
    int switched = 0;
    gt_status status = roll_to_record_days(storage, &switched, &events);
    if (status == GT_OK) {
        unsigned flush_events = 0;
        status = gt_storage_flush(storage, &flush_events);
        events |= flush_events;
    }
    if (events_out != NULL) {
        *events_out = events;
    }
    if (status != GT_OK) {
        return status;   /* no marker: this shutdown lost records */
    }

    int marker_handle = -1;
    if (storage->ops->open(storage->ctx, GT_STORAGE_MARKER_NAME, GT_FILE_CREATE,
                           &marker_handle) != GT_OK) {
        status = GT_ERR_IO;
    } else {
        storage->ops->close(storage->ctx, marker_handle);
        if (storage->ops->fsync_dir(storage->ctx) != GT_OK) {
            status = GT_ERR_IO;
        }
    }
    if (status != GT_OK && events_out != NULL) {
        *events_out |= GT_STORAGE_EV_WRITE_ERROR;
    }
    return status;
}

