/* Unit tests for watching the clock's sync state (src/clock_watch.c):
 * gt_clock_watch_init and gt_clock_watch_update.
 *
 * Purpose: prove the start and end of an unsynced spell are each reported
 * exactly once, with the spell's length, so storage and the hub can log
 * clock_unsynced / clock_synced (DESIGN.md System clock row, PF-13,
 * PF-21 case B) without logging on every check. Time is passed in, so
 * nothing waits. Run under make test / asan / memcheck. Implements CLW-01
 * through CLW-04.
 *
 * What these tests cannot prove: gt_clock_synced_now against a real
 * clock. Whether NTP has synced depends on the machine; it is seen on the
 * Pi after a reboot (the hub and storage log clock_synced). */
#include <stdint.h>

#include "check.h"
#include "clock_watch.h"

/* Marker for "update must not have written unsynced_ms_out". */
#define UNTOUCHED 0xDEADBEEFu

/* ---- CLW-01: a clock synced from the start reports nothing ----
 * The normal case: synced at every check, so no event and the length is
 * never written. */
static void test_clw01_synced_from_start_quiet(void)
{
    gt_clock_watch watch;
    gt_clock_watch_init(&watch);
    uint64_t unsynced_ms = UNTOUCHED;

    /* Invariant: checks 0 .. check_index - 1 all returned NONE. */
    for (uint64_t check_index = 0; check_index < 3; check_index++) {
        CHECK_EQ(gt_clock_watch_update(&watch, 1, check_index * 1000u, &unsynced_ms),
                 GT_CLOCK_EV_NONE);
    }
    CHECK_EQ(unsynced_ms, UNTOUCHED);
}

/* ---- CLW-02: an unsynced spell is reported once at its start ----
 * Three unsynced checks from 500 ms: UNSYNCED on the first, NONE on the
 * others, and the length is not written. */
static void test_clw02_unsynced_reported_once(void)
{
    gt_clock_watch watch;
    gt_clock_watch_init(&watch);
    uint64_t unsynced_ms = UNTOUCHED;

    CHECK_EQ(gt_clock_watch_update(&watch, 0, 500, &unsynced_ms), GT_CLOCK_EV_UNSYNCED);
    CHECK_EQ(gt_clock_watch_update(&watch, 0, 1500, &unsynced_ms), GT_CLOCK_EV_NONE);
    CHECK_EQ(gt_clock_watch_update(&watch, 0, 2500, &unsynced_ms), GT_CLOCK_EV_NONE);
    CHECK_EQ(unsynced_ms, UNTOUCHED);
}

/* ---- CLW-03: the spell's end carries its length ----
 * Unsynced from 500 ms, synced at 2500: SYNCED with unsynced_ms=2000. A
 * later synced check is NONE; unsynced again at 4000 starts a new spell,
 * and its end at 4600 reports 600, not a total. */
static void test_clw03_synced_reports_length(void)
{
    gt_clock_watch watch;
    gt_clock_watch_init(&watch);
    uint64_t unsynced_ms = UNTOUCHED;

    CHECK_EQ(gt_clock_watch_update(&watch, 0, 500, NULL), GT_CLOCK_EV_UNSYNCED);
    CHECK_EQ(gt_clock_watch_update(&watch, 1, 2500, &unsynced_ms), GT_CLOCK_EV_SYNCED);
    CHECK_EQ(unsynced_ms, 2000);
    CHECK_EQ(gt_clock_watch_update(&watch, 1, 3500, &unsynced_ms), GT_CLOCK_EV_NONE);

    CHECK_EQ(gt_clock_watch_update(&watch, 0, 4000, NULL), GT_CLOCK_EV_UNSYNCED);
    CHECK_EQ(gt_clock_watch_update(&watch, 1, 4600, &unsynced_ms), GT_CLOCK_EV_SYNCED);
    CHECK_EQ(unsynced_ms, 600);
}

/* ---- CLW-04: NULL is safe ----
 * A NULL watch is NONE for any input, init(NULL) is a no-op, and a NULL
 * length pointer at a spell's end still reports SYNCED. */
static void test_clw04_null_safe(void)
{
    gt_clock_watch_init(NULL);
    CHECK_EQ(gt_clock_watch_update(NULL, 0, 0, NULL), GT_CLOCK_EV_NONE);
    CHECK_EQ(gt_clock_watch_update(NULL, 1, 0, NULL), GT_CLOCK_EV_NONE);

    gt_clock_watch watch;
    gt_clock_watch_init(&watch);
    CHECK_EQ(gt_clock_watch_update(&watch, 0, 0, NULL), GT_CLOCK_EV_UNSYNCED);
    CHECK_EQ(gt_clock_watch_update(&watch, 1, 10, NULL), GT_CLOCK_EV_SYNCED);
}

static const test_case_t tests[] = {
    {"CLW-01", "a clock synced from the start is quiet", test_clw01_synced_from_start_quiet},
    {"CLW-02", "an unsynced spell is reported once", test_clw02_unsynced_reported_once},
    {"CLW-03", "the spell's end carries its length", test_clw03_synced_reports_length},
    {"CLW-04", "NULL is safe", test_clw04_null_safe},
};

int main(void)
{
    return RUN_TESTS(tests);
}

