/* Watching the wall clock's sync state (see clock_watch.h).
 *
 * Purpose: one place that decides whether the wall clock can be trusted
 * (gt_clock_synced_now, moved from storage_main so the hub can ask too)
 * and one tracker that turns a stream of checks into "spell started" /
 * "spell ended" events (gt_clock_watch, the logic storage's flush thread
 * used inline). The tracker does no I/O and reads no clock, so it is
 * tested without one (tests/test_clock_watch.c, CLW). */
#include "clock_watch.h"

#include <stddef.h>
#include <string.h>
#include <time.h>
#ifdef __linux__
#include <sys/timex.h>
#endif

/* The kernel's view first needs the date floor: a clock reading 1970 is
 * wrong whatever adjtimex says. */
int gt_clock_synced_now(void)
{
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    if ((uint64_t)now.tv_sec < GT_CLOCK_EARLIEST_VALID_S) {
        return 0;
    }
#ifdef __linux__
    struct timex clock_state;
    memset(&clock_state, 0, sizeof clock_state);   /* modes = 0: only read */
    int state = adjtimex(&clock_state);
    if (state == -1 || state == TIME_ERROR) {
        return 0;
    }
#endif
    return 1;
}

void gt_clock_watch_init(gt_clock_watch *watch)
{
    if (watch == NULL) {
        return;
    }
    watch->unsynced = 0;
    watch->unsynced_since_ms = 0;
}

/* A spell starts on the first unsynced check and ends on the first
 * synced one after it; every other check changes nothing. */
gt_clock_event gt_clock_watch_update(gt_clock_watch *watch, int synced, uint64_t now_ms,
                                     uint64_t *unsynced_ms_out)
{
    if (watch == NULL || synced != watch->unsynced) {
        return GT_CLOCK_EV_NONE;   /* no watch, or no change: synced and not in a spell, or the reverse */
    }
    if (!synced) {
        watch->unsynced = 1;
        watch->unsynced_since_ms = now_ms;
        return GT_CLOCK_EV_UNSYNCED;
    }
    watch->unsynced = 0;
    if (unsynced_ms_out != NULL) {
        *unsynced_ms_out = now_ms - watch->unsynced_since_ms;
    }
    return GT_CLOCK_EV_SYNCED;
}

