import sys

server_h, flusher_c, main_c = sys.argv[1:4]


def edit(path, pairs):
    source = open(path, encoding="utf-8").read()
    for old, new in pairs:
        if source.count(old) != 1:
            sys.exit(path + ": not exactly once: " + old[:70])
        source = source.replace(old, new)
    open(path, "w", encoding="utf-8").write(source)


edit(server_h, [
    ('#include <stdint.h>\n#include "gt_log.h"\n',
     '#include <stdint.h>\n#include "clock_watch.h"\n#include "gt_log.h"\n'),
    ("""    int                clock_unsynced;   /* 1 during an unsynced spell (PF-13) */
    uint64_t           unsynced_since_ms;  /* now_ms of the spell's first pass */
""",
     """    gt_clock_watch     clock_watch;      /* the current unsynced spell, if any (PF-13) */
"""),
])

edit(flusher_c, [
    ("""    flusher->clock_unsynced = 0;
    flusher->unsynced_since_ms = 0;
""",
     """    gt_clock_watch_init(&flusher->clock_watch);
"""),
    ("""static void log_clock_change(gt_flusher *flusher, uint64_t now_ms, int clock_synced)
{
    if (!clock_synced && !flusher->clock_unsynced) {
        flusher->clock_unsynced = 1;
        flusher->unsynced_since_ms = now_ms;
        if (flusher->log != NULL) {
            flusher->log(flusher->log_ctx, GT_LOG_WARN, "clock_unsynced", NULL);
        }
    } else if (clock_synced && flusher->clock_unsynced) {
        flusher->clock_unsynced = 0;
        if (flusher->log != NULL) {
            char fields[48];
            snprintf(fields, sizeof fields, "unsynced_ms=%llu",
